        for num in nums:
            # cost for this num to become a multiple of lcm(s)
            cost = [0] * full
            for s in range(1, full):
                L = sub_lcm[s]
                cost[s] = ((num + L - 1) // L) * L - num

            new_dp = dp[:]  # corresponds to assigning empty subset (cost 0)
            for mask in range(full):
                cur = dp[mask]
                if cur == INF:
                    continue
